#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# firebase-config.sh <platform>  (stream P, P3b)
# ---------------------------------------------------------------------------
# Materializes the Firebase client configuration of a release build from
# GitHub secrets into git-ignored files. The values are public identifiers,
# not secrets, but they stay out of git so forks and dev builds can never
# talk to our Firebase project (contract X0-P6, gap-platform.md §4).
#
# platform: web | android | ios | macos | windows | linux
#
# Inputs (env, all optional — a missing one means "this build has no push"):
#   FIREBASE_CLIENT_CONFIG_JSON_B64               base64 of a FLAT JSON object
#                                                 with the FIREBASE_* dart-define keys
#   FIREBASE_ANDROID_GOOGLE_SERVICES_JSON_B64     base64 of google-services.json
#   FIREBASE_APPLE_GOOGLE_SERVICE_INFO_PLIST_B64  base64 of GoogleService-Info.plist
#                                                 (only if stream N needs it, R-P12)
#   JAY_APP_DIR                                   app dir (tests; default src/client/calltype)
#
# Outputs (relative to the app dir):
#   build-defines/firebase.json   ALWAYS; `{}` without config. Pass it to
#                                 flutter build --dart-define-from-file=...
#   web/firebase-config.js        web only, when the web keys are complete
#   android/app/google-services.json          android only, when its secret is set
#   {ios,macos}/Runner/GoogleService-Info.plist  apple only, when its secret is set
#
# Never prints a decoded value and never uses `set -x`: the run log is public
# during the public window.
# ---------------------------------------------------------------------------
set -euo pipefail

APP_ID=cz.zcloud.jay
PLATFORM=${1:-}
case "$PLATFORM" in
  web | android | ios | macos | windows | linux) ;;
  *)
    echo "::error::usage: firebase-config.sh web|android|ios|macos|windows|linux" >&2
    exit 2
    ;;
esac

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
APP=${JAY_APP_DIR:-$ROOT/src/client/calltype}
DEFINES_DIR="$APP/build-defines"
DEFINES="$DEFINES_DIR/firebase.json"
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

fail() {
  echo "::error::$*" >&2
  exit 1
}
warn() { echo "::warning::$*"; }

# Secrets pasted from a terminal often carry line breaks or spaces; base64
# ignores neither on every platform, so strip them first. `base64 --decode`
# works with GNU coreutils (ubuntu) and macOS 13+ runners alike.
decode_b64() { # <value> <out file>
  printf '%s' "$1" | tr -d ' \r\n\t' | base64 --decode >"$2" 2>/dev/null ||
    fail "a Firebase secret is not valid base64"
}

mkdir -p "$DEFINES_DIR"

# --- 1. dart-defines ---------------------------------------------------------
HAVE_CONFIG=false
if [ -n "${FIREBASE_CLIENT_CONFIG_JSON_B64:-}" ]; then
  decode_b64 "$FIREBASE_CLIENT_CONFIG_JSON_B64" "$WORK/client.json"
  jq -e 'type == "object" and all(.[]; type == "string")' "$WORK/client.json" >/dev/null 2>&1 ||
    fail "FIREBASE_CLIENT_CONFIG_JSON_B64 must decode to a flat JSON object of strings"
  jq -e '(.FIREBASE_PROJECT_ID // "") | length > 0' "$WORK/client.json" >/dev/null ||
    fail "FIREBASE_CLIENT_CONFIG_JSON_B64 has no FIREBASE_PROJECT_ID"
  # The Apple bundle id is our app id or absent; anything else is another
  # app's config pasted by mistake.
  jq -e --arg id "$APP_ID" '(.FIREBASE_APPLE_BUNDLE_ID // $id) == $id' "$WORK/client.json" >/dev/null ||
    fail "FIREBASE_APPLE_BUNDLE_ID in the client config is not $APP_ID"
  HAVE_CONFIG=true
fi

if [ "$HAVE_CONFIG" = true ] && [ "$PLATFORM" != windows ] && [ "$PLATFORM" != linux ]; then
  # Only FIREBASE_* keys pass: the secret must not be able to override other
  # dart-defines such as API_BASE_URL or JAY_DISTRIBUTION.
  jq -S 'with_entries(select(.key | test("^FIREBASE_[A-Z0-9_]+$")))' "$WORK/client.json" >"$DEFINES"
else
  # Windows/Linux have no Firebase in this app (FirebaseConfig returns null),
  # so their binaries do not need to carry the identifiers at all.
  echo '{}' >"$DEFINES"
  if [ "$HAVE_CONFIG" = false ]; then
    warn "Firebase not configured for $PLATFORM — push will report notConfigured (FIREBASE_CLIENT_CONFIG_JSON_B64 not set)"
  fi
fi

# --- 2. platform files -------------------------------------------------------
case "$PLATFORM" in
  web)
    if [ "$HAVE_CONFIG" = true ] &&
      jq -e '[.FIREBASE_WEB_API_KEY, .FIREBASE_WEB_APP_ID, .FIREBASE_MESSAGING_SENDER_ID]
             | all(. != null and . != "")' "$WORK/client.json" >/dev/null; then
      # Keys exactly as the Firebase JS SDK expects them; the service worker
      # (stream N) loads this file with importScripts('firebase-config.js').
      {
        echo '// Generated by .github/scripts/firebase-config.sh for a release build.'
        printf 'self.JAY_FIREBASE_CONFIG = %s;\n' "$(jq -c '{
          apiKey: .FIREBASE_WEB_API_KEY,
          authDomain: (.FIREBASE_WEB_AUTH_DOMAIN // ""),
          projectId: .FIREBASE_PROJECT_ID,
          storageBucket: (.FIREBASE_STORAGE_BUCKET // ""),
          messagingSenderId: .FIREBASE_MESSAGING_SENDER_ID,
          appId: .FIREBASE_WEB_APP_ID
        }' "$WORK/client.json")"
      } >"$APP/web/firebase-config.js"
    elif [ "$HAVE_CONFIG" = true ]; then
      # Keep the committed `null` so the service worker no-ops, matching the
      # Dart side, which also treats incomplete web keys as not configured.
      warn "web keys incomplete in the client config — web push stays notConfigured"
    fi
    ;;
  android)
    if [ -n "${FIREBASE_ANDROID_GOOGLE_SERVICES_JSON_B64:-}" ]; then
      decode_b64 "$FIREBASE_ANDROID_GOOGLE_SERVICES_JSON_B64" "$WORK/gs.json"
      jq -e 'type == "object"' "$WORK/gs.json" >/dev/null 2>&1 ||
        fail "FIREBASE_ANDROID_GOOGLE_SERVICES_JSON_B64 is not JSON"
      # The google-services Gradle plugin picks the client by package name;
      # a file without ours would build fine and fail only on the device.
      jq -e --arg id "$APP_ID" \
        'any(.client[]?; .client_info.android_client_info.package_name == $id)' "$WORK/gs.json" >/dev/null ||
        fail "google-services.json has no Android client for $APP_ID"
      if [ "$HAVE_CONFIG" = true ]; then
        a=$(jq -r '.project_info.project_id // ""' "$WORK/gs.json")
        b=$(jq -r '.FIREBASE_PROJECT_ID' "$WORK/client.json")
        [ "$a" = "$b" ] || fail "google-services.json and the client config belong to different Firebase projects"
      fi
      cp "$WORK/gs.json" "$APP/android/app/google-services.json"
    else
      warn "FIREBASE_ANDROID_GOOGLE_SERVICES_JSON_B64 not set — no google-services.json; FCM in a killed process may not start"
    fi
    ;;
  ios | macos)
    if [ -n "${FIREBASE_APPLE_GOOGLE_SERVICE_INFO_PLIST_B64:-}" ]; then
      decode_b64 "$FIREBASE_APPLE_GOOGLE_SERVICE_INFO_PLIST_B64" "$WORK/gs.plist"
      # python3 is on every hosted runner; plutil is macOS-only.
      bid=$(python3 -c 'import plistlib,sys; print(plistlib.load(open(sys.argv[1],"rb")).get("BUNDLE_ID",""))' \
        "$WORK/gs.plist" 2>/dev/null) || fail "FIREBASE_APPLE_GOOGLE_SERVICE_INFO_PLIST_B64 is not a plist"
      [ "$bid" = "$APP_ID" ] || fail "GoogleService-Info.plist BUNDLE_ID is not $APP_ID"
      cp "$WORK/gs.plist" "$APP/$PLATFORM/Runner/GoogleService-Info.plist"
    fi
    ;;
  windows | linux) ;;
esac

echo "firebase-config: $PLATFORM configured=$HAVE_CONFIG defines=${DEFINES#"$APP"/}"
